style.css:
body {
    background-image: url('https://i.pinimg.com/736x/0b/64/2f/0b642f4fe2cdd25caf9694a0a98fc263.jpg'); /* Roblox-themed background image */
    background-repeat: no-repeat;
    background-size: cover; /* Ensures the image covers the entire background */
    color: #FFFFFF; /* White text for contrast */
}

h1, h2, h3, h4, h5, h6 {
    color: #F1C40F; /* Bright yellow for headings */
}

a {
    color: #3498DB; /* Roblox blue for links */
}

a:hover {
    color: #1ABC9C; /* Change link color on hover */
}
